/**
 * Link to QR Code Generator - Main Application Logic
 * Implements PRD Functional Requirements FR-01 to FR-06
 */

(function () {
  'use strict';

  // DOM Elements
  const urlInput = document.getElementById('urlInput');
  const clearInputBtn = document.getElementById('clearInputBtn');
  const generateBtn = document.getElementById('generateBtn');
  const errorBox = document.getElementById('errorBox');
  const errorMessage = document.getElementById('errorMessage');

  const inputSection = document.getElementById('inputSection');
  const resultSection = document.getElementById('resultSection');

  const qrContainer = document.getElementById('qrContainer');
  const urlPreviewText = document.getElementById('urlPreviewText');
  const copyUrlBtn = document.getElementById('copyUrlBtn');
  const copyBtnLabel = document.getElementById('copyBtnLabel');
  const downloadBtn = document.getElementById('downloadBtn');
  const resetBtn = document.getElementById('resetBtn');
  const toast = document.getElementById('toast');
  const toastMessage = document.getElementById('toastMessage');

  let currentQrCode = null;
  let currentTargetUrl = '';
  let toastTimer = null;

  /**
   * PRD FR-02: URL Validation Logic
   * @param {string} input - User input string
   * @returns {{isValid: boolean, url: string, errorMsg?: string}}
   */
  function validateUrl(input) {
    const trimmed = (input || '').trim();

    // Condition: Input kosong
    if (!trimmed) {
      return {
        isValid: false,
        url: '',
        errorMsg: 'Silakan masukkan URL.'
      };
    }

    // Try normalizing and parsing as URL
    let urlToTest = trimmed;
    // If protocol is missing, check if it starts with valid domain format
    if (!/^https?:\/\//i.test(urlToTest)) {
      // Check if it looks like a valid hostname / web link
      const domainPattern = /^[a-zA-Z0-9][-a-zA-Z0-9]*(\.[a-zA-Z0-9][-a-zA-Z0-9]*)+(:\d+)?(\/.*)?$/i;
      if (domainPattern.test(urlToTest)) {
        urlToTest = 'https://' + urlToTest;
      }
    }

    try {
      const parsed = new URL(urlToTest);
      // Valid protocols must be http: or https:
      if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
        return {
          isValid: false,
          url: '',
          errorMsg: 'URL tidak valid. Silakan masukkan link yang benar.'
        };
      }

      // Check for valid hostname containing at least a dot (e.g. example.com) or localhost
      if (!parsed.hostname || (!parsed.hostname.includes('.') && parsed.hostname !== 'localhost')) {
        return {
          isValid: false,
          url: '',
          errorMsg: 'URL tidak valid. Silakan masukkan link yang benar.'
        };
      }

      return {
        isValid: true,
        url: parsed.href
      };
    } catch (e) {
      return {
        isValid: false,
        url: '',
        errorMsg: 'URL tidak valid. Silakan masukkan link yang benar.'
      };
    }
  }

  /**
   * Display error message in error box
   * @param {string} msg 
   */
  function showError(msg) {
    errorMessage.textContent = msg;
    errorBox.classList.add('active');
    urlInput.setAttribute('aria-invalid', 'true');
    urlInput.focus();
  }

  /**
   * Clear error message
   */
  function clearError() {
    errorBox.classList.remove('active');
    urlInput.removeAttribute('aria-invalid');
  }

  /**
   * Toast notification display
   * @param {string} message 
   */
  function showToast(message) {
    if (toastTimer) clearTimeout(toastTimer);
    toastMessage.textContent = message;
    toast.classList.add('show');
    toastTimer = setTimeout(() => {
      toast.classList.remove('show');
    }, 2400);
  }

  /**
   * PRD FR-03 & FR-04: Generate QR Code & Preview State
   */
  function generateQRCode() {
    clearError();

    const rawInput = urlInput.value;
    const validation = validateUrl(rawInput);

    if (!validation.isValid) {
      showError(validation.errorMsg);
      return;
    }

    try {
      currentTargetUrl = validation.url;

      // Clear previous QR code
      qrContainer.innerHTML = '';

      // Generate QR Code with crisp dimensions
      currentQrCode = new QRCode(qrContainer, {
        text: currentTargetUrl,
        width: 240,
        height: 240,
        colorDark: '#090d16',
        colorLight: '#ffffff',
        correctLevel: QRCode.CorrectLevel.H
      });

      // Update URL Preview badge text
      urlPreviewText.textContent = currentTargetUrl;
      urlPreviewText.title = currentTargetUrl;

      // Transition to Result State
      inputSection.style.display = 'none';
      resultSection.classList.add('active');

      // Reset copy button state
      copyUrlBtn.classList.remove('copied');
      copyBtnLabel.textContent = 'Salin';

    } catch (err) {
      console.error('QR Generation failed:', err);
      showError('QR Code gagal dibuat. Silakan coba lagi.');
    }
  }

  /**
   * PRD FR-05: Download QR Code as PNG with high resolution
   */
  function downloadQRCode() {
    try {
      // Find canvas or image inside qrContainer
      const existingCanvas = qrContainer.querySelector('canvas');
      const existingImg = qrContainer.querySelector('img');

      // Create a high-res master export canvas (1024x1024) with quiet-zone padding for pristine quality
      const exportCanvas = document.createElement('canvas');
      const exportSize = 1024;
      const padding = 80;
      exportCanvas.width = exportSize;
      exportCanvas.height = exportSize;

      const ctx = exportCanvas.getContext('2d');
      // Fill background
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, exportSize, exportSize);

      const drawAndSave = (sourceElement) => {
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(sourceElement, padding, padding, exportSize - padding * 2, exportSize - padding * 2);

        exportCanvas.toBlob((blob) => {
          if (!blob) {
            triggerFallbackDownload();
            return;
          }
          const downloadLink = document.createElement('a');
          const objectUrl = URL.createObjectURL(blob);
          downloadLink.href = objectUrl;
          downloadLink.download = 'qr-code.png';
          document.body.appendChild(downloadLink);
          downloadLink.click();
          document.body.removeChild(downloadLink);
          URL.revokeObjectURL(objectUrl);
          showToast('QR Code berhasil diunduh (qr-code.png)!');
        }, 'image/png');
      };

      if (existingCanvas && existingCanvas.width > 0) {
        drawAndSave(existingCanvas);
      } else if (existingImg && existingImg.src) {
        if (existingImg.complete) {
          drawAndSave(existingImg);
        } else {
          existingImg.onload = () => drawAndSave(existingImg);
        }
      } else {
        throw new Error('Canvas or Image not found');
      }

    } catch (err) {
      console.error('Download QR Code failed:', err);
      triggerFallbackDownload();
    }
  }

  function triggerFallbackDownload() {
    const existingImg = qrContainer.querySelector('img');
    const existingCanvas = qrContainer.querySelector('canvas');

    const downloadLink = document.createElement('a');
    downloadLink.download = 'qr-code.png';

    if (existingImg && existingImg.src) {
      downloadLink.href = existingImg.src;
      document.body.appendChild(downloadLink);
      downloadLink.click();
      document.body.removeChild(downloadLink);
      showToast('QR Code berhasil diunduh!');
    } else if (existingCanvas) {
      downloadLink.href = existingCanvas.toDataURL('image/png');
      document.body.appendChild(downloadLink);
      downloadLink.click();
      document.body.removeChild(downloadLink);
      showToast('QR Code berhasil diunduh!');
    } else {
      showError('QR Code gagal diunduh.');
    }
  }

  /**
   * PRD FR-06: Reset / Create New
   * Restores initial state, clears input, QR code, and error messages
   */
  function resetToInitialState() {
    // Reset state values
    currentTargetUrl = '';
    currentQrCode = null;
    qrContainer.innerHTML = '';
    urlInput.value = '';
    clearInputBtn.classList.remove('visible');

    // Clear error
    clearError();

    // Switch view
    resultSection.classList.remove('active');
    inputSection.style.display = 'flex';

    // Refocus input
    setTimeout(() => {
      urlInput.focus();
    }, 100);
  }

  /**
   * Copy target URL to clipboard
   */
  async function copyTargetUrl() {
    if (!currentTargetUrl) return;

    try {
      if (navigator.clipboard && window.isSecureContext) {
        await navigator.clipboard.writeText(currentTargetUrl);
      } else {
        // Fallback for non-https / legacy context
        const tempInput = document.createElement('input');
        tempInput.value = currentTargetUrl;
        document.body.appendChild(tempInput);
        tempInput.select();
        document.execCommand('copy');
        document.body.removeChild(tempInput);
      }

      copyUrlBtn.classList.add('copied');
      copyBtnLabel.textContent = 'Tersalin!';
      showToast('URL berhasil disalin ke papan klip!');

      setTimeout(() => {
        copyUrlBtn.classList.remove('copied');
        copyBtnLabel.textContent = 'Salin';
      }, 2000);
    } catch (err) {
      console.warn('Copy failed', err);
      showToast('Gagal menyalin URL');
    }
  }

  // ==========================================================================
  // Event Listeners
  // ==========================================================================

  // Input change / typing events
  urlInput.addEventListener('input', () => {
    if (urlInput.value.length > 0) {
      clearInputBtn.classList.add('visible');
    } else {
      clearInputBtn.classList.remove('visible');
    }
    clearError();
  });

  // Enter key press triggers generation
  urlInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      generateQRCode();
    }
  });

  // Clear button click
  clearInputBtn.addEventListener('click', () => {
    urlInput.value = '';
    clearInputBtn.classList.remove('visible');
    clearError();
    urlInput.focus();
  });

  // Generate button click
  generateBtn.addEventListener('click', generateQRCode);

  // Download button click
  downloadBtn.addEventListener('click', downloadQRCode);

  // Reset button click
  resetBtn.addEventListener('click', resetToInitialState);

  // Copy URL button click
  copyUrlBtn.addEventListener('click', copyTargetUrl);

  // Initial auto focus
  window.addEventListener('DOMContentLoaded', () => {
    urlInput.focus();
  });

})();

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 4173;
const MIME_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon'
};

const server = http.createServer((req, res) => {
  let reqPath = req.url.split('?')[0];
  if (reqPath === '/') reqPath = '/index.html';
  const filePath = path.join(__dirname, reqPath);

  fs.readFile(filePath, (err, content) => {
    if (err) {
      if (err.code === 'ENOENT') {
        res.writeHead(404, { 'Content-Type': 'text/plain' });
        res.end('404 Not Found');
      } else {
        res.writeHead(500, { 'Content-Type': 'text/plain' });
        res.end('500 Internal Server Error');
      }
    } else {
      const ext = path.extname(filePath).toLowerCase();
      res.writeHead(200, { 'Content-Type': MIME_TYPES[ext] || 'application/octet-stream' });
      res.end(content);
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}/`);
});
